#!/bin/bash
PURPLE="\e[1;35m"
BLUE="\e[1;34m"
GREEN="\e[1;32m"
WHITE="\e[1;37m"
RED="\e[1;31m"
NC="\e[0m"
while true; do clear; echo -e "${PURPLE}Scripted ${GREEN}By ${BLUE}Albert ${WHITE}Tech ${GREEN}Inc${NC}"; echo -e "${PURPLE}┌──────────────────────────────────────────────────┐${NC}"; echo -e "${PURPLE}│${WHITE}                  ${BLUE}SUB MENU MANAGER                ${WHITE}${PURPLE}│${NC}"; echo -e "${PURPLE}├──────────────────────────────────────────────────┤${NC}"; echo -e "${PURPLE}│${WHITE}  Domain : ${BLUE}$(cat /etc/xray/domain 2>/dev/null || echo "No Domain")        ${PURPLE}│${NC}"; echo -e "${PURPLE}└──────────────────────────────────────────────────┘${NC}"; echo -e ""; echo -e "${PURPLE}┌──────────────────────────────────────────────────┐${NC}"; echo -e "${PURPLE}│${NC}                                                  ${PURPLE}│${NC}"; printf "${PURPLE}│${WHITE}  ${GREEN}%-2s ${PURPLE}│${WHITE}  ${BLUE}%-40s ${PURPLE}│${NC}\n" "1" "Create Account"; echo -e "${PURPLE}│${NC}                                                  ${PURPLE}│${NC}"; printf "${PURPLE}│${WHITE}  ${GREEN}%-2s ${PURPLE}│${WHITE}  ${BLUE}%-40s ${PURPLE}│${NC}\n" "2" "Trial Account"; echo -e "${PURPLE}│${NC}                                                  ${PURPLE}│${NC}"; printf "${PURPLE}│${WHITE}  ${GREEN}%-2s ${PURPLE}│${WHITE}  ${BLUE}%-40s ${PURPLE}│${NC}\n" "3" "Delete Account"; echo -e "${PURPLE}│${NC}                                                  ${PURPLE}│${NC}"; printf "${PURPLE}│${WHITE}  ${GREEN}%-2s ${PURPLE}│${WHITE}  ${BLUE}%-40s ${PURPLE}│${NC}\n" "0" "Back to Main Menu"; echo -e "${PURPLE}│${NC}                                                  ${PURPLE}│${NC}"; echo -e "${PURPLE}└──────────────────────────────────────────────────┘${NC}"; echo -e ""; echo -ne "${GREEN}Select option : ${NC}"; read opt; case $opt in 0|00) menu; exit 0;; *) echo -e "\n${RED}[!] Invalid option.${NC}"; sleep 1;; esac; done
